# Example dummy for tests (remove if real exists)
def calculate_stock_volatility(prices):
    # Volatility: std deviation (for test purposes, use a trivial stub or real calculation separately)
    if not prices:
        return 0.0
    mean = sum(prices) / len(prices)
    var = sum((p - mean)**2 for p in prices) / len(prices)
    return var**0.5

def portfolio_risk_assessment(portfolio_dict):
    '''
    portfolio_dict: dict where keys are stock names, values have 'prices' list and 'allocation' float
    For each stock, call calculate_stock_volatility(prices), multiply by allocation, sum all.
    Returns float (total portfolio risk)
    '''
    total_risk = 0.0
    for stock, info in portfolio_dict.items():
        volatility = calculate_stock_volatility(info['prices'])
        total_risk += volatility * info['allocation']
    return total_risk

