def portfolio_risk_assessment(portfolio):
    '''
    Takes a portfolio dict where keys are stock names, and values are dicts with:
      - 'prices': list of floats (stock prices)
      - 'allocation': float (fraction allocation, e.g. 0.2 for 20%)
    For each stock, calculates stock volatility, multiplies by allocation, sums these for portfolio risk.
    Returns total portfolio risk as float.
    '''
    # Chain-of-thought breakdown:
    # 1. For each stock in the portfolio:
    #    a. Extract 'prices' and 'allocation'.
    #    b. Call calculate_stock_volatility(prices) to get volatility.
    #    c. Multiply volatility by allocation.
    # 2. Sum up all weighted volatilities.
    # 3. Return the sum as portfolio risk.

    total_risk = 0.0

    for stock in portfolio:
        stock_data = portfolio[stock]
        prices = stock_data.get('prices', [])
        allocation = stock_data.get('allocation', 0.0)

        # Defensive check: If allocation or prices missing or not valid, skip
        if not isinstance(prices, list) or not isinstance(allocation, (float, int)):
            continue

        stock_volatility = calculate_stock_volatility(prices)
        weighted_volatility = stock_volatility * allocation
        total_risk += weighted_volatility

    return total_risk


