def aggregate_temperature(sensor_strings):
    '''
    Takes a list of raw sensor strings. Uses parse_sensor_reading to parse each one.
    Collects all temperature values that are not None. 
    Returns average of all temperatures rounded to 2 decimals. 
    Returns 0.0 if no valid temperatures.
    '''
    temps = []
    for sensor_string in sensor_strings:
        reading = parse_sensor_reading(sensor_string)
        temp = reading.get('temperature')
        if temp is not None:
            temps.append(temp)
    if not temps:
        return 0.0
    return round(sum(temps) / len(temps), 2)
